// ═══ flatMapToInt — ONE step, no boxing ═══
// Each account has multiple transaction quantities:
record Account(String id, int[] transactionQuantities) {}

List<Account> accounts = List.of(
    new Account("SAV2001", new int[]{100, 50, 200}),
    new Account("CUR3001", new int[]{80, 150}));

int totalQuantity = accounts.stream()
    .flatMapToInt(a -> IntStream.of(a.transactionQuantities()))  // each Account → IntStream
    .sum();
// 100 + 50 + 200 + 80 + 150 = 580. ONE step. Zero Integer objects.

// ═══ WITHOUT flatMapToInt — TWO steps, boxing ═══
int totalVerbose = accounts.stream()
    .flatMap(a -> Arrays.stream(a.transactionQuantities()).boxed())  // IntStream → Stream<Integer>!
    .mapToInt(Integer::intValue)   // Stream<Integer> → IntStream (unboxing!)
    .sum();
// Same result 580, but: boxed() created 5 Integer objects, then mapToInt unboxed them.

// ═══ flatMapToDouble — same for doubles ═══
record Trade(String symbol, double[] dailyPrices) {}
List<Trade> trades = List.of(
    new Trade("RELIANCE", new double[]{2450.50, 2445.00, 2460.75}),
    new Trade("TCS", new double[]{3520.00, 3515.50}));

double avgPrice = trades.stream()
    .flatMapToDouble(t -> DoubleStream.of(t.dailyPrices()))
    .average()
    .orElse(0.0);
// All 5 prices flattened into one DoubleStream. average() in one pass.

// ═══ flatMapToLong — for large values ═══
record Portfolio(String owner, long[] transactionAmountsCents) {}
long totalCents = List.of(
    new Portfolio("Rajesh", new long[]{24505000L, 17600000L}),
    new Portfolio("Priya", new long[]{33015000L}))
    .stream()
    .flatMapToLong(p -> LongStream.of(p.transactionAmountsCents()))
    .sum();
