package com.bank.flat;

import org.junit.jupiter.api.Test;
import java.util.*;
import java.util.stream.*;
import static org.assertj.core.api.Assertions.*;

class FlatMapToPrimitiveTest {

    @Test void flatMapToIntFlattensToOnePrimitiveStream() {
        List<int[]> arrays = List.of(new int[]{1, 2}, new int[]{3, 4, 5});
        int sum = arrays.stream()
            .flatMapToInt(IntStream::of)
            .sum();
        assertThat(sum).isEqualTo(15);
    }

    @Test void flatMapToDoubleForNestedDoubles() {
        List<double[]> prices = List.of(new double[]{100.5, 200.3}, new double[]{300.7});
        double avg = prices.stream()
            .flatMapToDouble(DoubleStream::of)
            .average().orElse(0);
        assertThat(avg).isCloseTo(200.5, within(0.1));
    }

    @Test void flatMapToLongForLargeValues() {
        List<long[]> amounts = List.of(new long[]{Long.MAX_VALUE - 1}, new long[]{1});
        long sum = amounts.stream()
            .flatMapToLong(LongStream::of)
            .sum();
        assertThat(sum).isEqualTo(Long.MAX_VALUE);
    }

    @Test void flatMapToIntVsFlatMapPlusMapToInt() {
        List<List<Integer>> nested = List.of(List.of(1, 2), List.of(3, 4));

        // flatMapToInt: direct to primitive
        int sum1 = nested.stream()
            .flatMapToInt(list -> list.stream().mapToInt(Integer::intValue))
            .sum();

        // flatMap + mapToInt: intermediate Stream<Integer>
        int sum2 = nested.stream()
            .flatMap(Collection::stream)      // Stream<Integer> — boxing!
            .mapToInt(Integer::intValue)       // IntStream — unboxing!
            .sum();

        assertThat(sum1).isEqualTo(sum2);  // same result, flatMapToInt is more efficient
    }

    private static org.assertj.core.data.Offset<Double> within(double d) {
        return org.assertj.core.data.Offset.offset(d);
    }
}
