package com.bank.java8;

import org.junit.jupiter.api.Test;
import java.util.List;
import java.util.stream.IntStream;
import static org.assertj.core.api.Assertions.assertThat;

class FlatMapToIntTest {

    @Test
    void flattenToPrimitiveStreamNoBoxing() {
        List<int[]> perAccount = List.of(
            new int[]{5000, 2000},
            new int[]{10000},
            new int[]{3000, 4000, 1000});

        int total = perAccount.stream()
            .flatMapToInt(IntStream::of)   // one-to-many → primitive IntStream, no boxing
            .sum();

        assertThat(total).isEqualTo(25000);
    }
}
